/* ============================================================
   Feature 3 (this batch): Milestone / partial invoice
   ============================================================ */
async function generateMilestoneInvoice(orderId, milestone) {
  const order = printLog.find(o => o.id === orderId);
  if (!order || !milestone) return;
  // Build a temporary order-like object with the milestone amount
  const tempOrder = Object.assign({}, order, {
    price: milestone.amount,
    _milestoneLabel: milestone.label,
    _milestoneTotal: order.price,
    _milestonePct: milestone.percentage,
  });
  milestone.issuedAt = new Date().toISOString().split('T')[0];
  saveAll();
  await renderInvoiceForOrder(tempOrder);
}

function openMilestoneInvoices(orderId) {
  const order = printLog.find(o => o.id === orderId);
  if (!order) return;
  if (!order.milestoneInvoices) order.milestoneInvoices = [];

  function listHtml() {
    if (order.milestoneInvoices.length === 0) {
      return `<p style="color:var(--text-muted);font-size:13px;">${escapeHtml(t('waste.empty'))}</p>`;
    }
    return `<table style="width:100%;font-size:12.5px;border-collapse:collapse;">
      <thead><tr style="border-bottom:1px solid var(--border-soft);color:var(--text-muted);">
        <th style="padding:5px 8px;text-align:left;">${escapeHtml(t('ord.milestone_label'))}</th>
        <th style="padding:5px 8px;text-align:right;">${escapeHtml(t('ord.milestone_pct'))}</th>
        <th style="padding:5px 8px;text-align:right;">${escapeHtml(t('ord.milestone_amount'))}</th>
        <th style="padding:5px 8px;">${escapeHtml(t('ord.milestone_issued'))}</th>
        <th></th>
      </tr></thead>
      <tbody>
        ${order.milestoneInvoices.map((m, i) => `<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
          <td style="padding:6px 8px;">${escapeHtml(m.label)}</td>
          <td style="padding:6px 8px;text-align:right;">${escapeHtml(String(m.percentage))}%</td>
          <td style="padding:6px 8px;text-align:right;">${fmtPrice(m.amount)}</td>
          <td style="padding:6px 8px;color:var(--text-muted);">${m.issuedAt ? escapeHtml(m.issuedAt) : '—'}</td>
          <td style="padding:6px 8px;">
            <button class="btn small" data-mi="${i}">${escapeHtml(t('ord.milestone_issue'))}</button>
            <button class="btn danger small" data-mi-del="${i}" style="margin-inline-start:4px;">×</button>
          </td>
        </tr>`).join('')}
      </tbody>
    </table>`;
  }

  openFormModal({
    title: `${t('ord.milestone_invoices')} — ${escapeHtml(order.id)}`,
    sizeLg: true,
    noSave: true,
    bodyHtml: `
      <div id="milestoneListWrap">${listHtml()}</div>
      <hr class="divider" style="margin:16px 0;">
      <div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px;align-items:end;">
        <div>
          <label style="margin:0;">${escapeHtml(t('ord.milestone_label'))}</label>
          <input type="text" id="msLabel" placeholder="e.g. Deposit" style="font-size:12.5px;">
        </div>
        <div>
          <label style="margin:0;">${escapeHtml(t('ord.milestone_pct'))} (%)</label>
          <input type="number" id="msPct" min="1" max="100" step="1" placeholder="50" style="font-size:12.5px;">
        </div>
        <div>
          <label style="margin:0;">${escapeHtml(t('ord.milestone_amount'))} (${currencySymbol()})</label>
          <input type="number" id="msAmount" min="0" step="0.01" placeholder="0.00" style="font-size:12.5px;">
        </div>
      </div>
      <div style="display:flex;gap:8px;margin-top:10px;">
        <button class="btn small primary" id="btnAddMilestone">${escapeHtml(t('ord.milestone_add'))}</button>
      </div>`,
    onMount(modal) {
      const wrap = modal.querySelector('#milestoneListWrap');
      function refresh() { wrap.innerHTML = listHtml(); wireIssue(); }
      function wireIssue() {
        wrap.querySelectorAll('[data-mi]').forEach(btn => {
          btn.addEventListener('click', () => {
            generateMilestoneInvoice(orderId, order.milestoneInvoices[+btn.dataset.mi]);
          });
        });
        wrap.querySelectorAll('[data-mi-del]').forEach(btn => {
          btn.addEventListener('click', () => {
            order.milestoneInvoices.splice(+btn.dataset['mi-del'] ?? +btn.getAttribute('data-mi-del'), 1);
            saveAll(); refresh();
          });
        });
      }
      wireIssue();
      // Auto-compute amount when % changes
      modal.querySelector('#msPct')?.addEventListener('input', (e) => {
        const pct = parseFloat(e.target.value) || 0;
        const amtEl = modal.querySelector('#msAmount');
        if (amtEl && order.price) amtEl.value = fmtMoney(+order.price * pct / 100);
      });
      modal.querySelector('#btnAddMilestone').addEventListener('click', () => {
        const label = modal.querySelector('#msLabel').value.trim() || 'Milestone';
        const pct = parseFloat(modal.querySelector('#msPct').value) || 0;
        const amount = parseFloat(modal.querySelector('#msAmount').value) || 0;
        order.milestoneInvoices.push({ id: uid('MS'), label, percentage: pct, amount, issuedAt: null });
        saveAll(); refresh();
        modal.querySelector('#msLabel').value = '';
        modal.querySelector('#msPct').value = '';
        modal.querySelector('#msAmount').value = '';
      });
    }
  });
}

/* ============================================================
   Feature 4 (this batch): AP — supplier invoice recording
   ============================================================ */
function recordSupplierInvoice(poId) {
  const po = purchaseOrders.find(p => p.id === poId);
  if (!po) return;
  openFormModal({
    title: t('po.ap_record'),
    sizeLg: false,
    saveLabel: t('common.save'),
    bodyHtml: `
      <label>${escapeHtml(t('po.sup_inv_num'))}</label>
      <input type="text" id="poSupInvNum" placeholder="${escapeHtml(t('po.sup_inv_num'))}" value="${escapeHtml(po.supplierInvoice?.number || '')}">
      <label style="margin-top:12px;">${escapeHtml(t('po.sup_inv_amount'))} (${currencySymbol()})</label>
      <input type="number" id="poSupInvAmount" min="0" step="0.01" value="${po.supplierInvoice?.amount || ''}">
      <label style="margin-top:12px;">${escapeHtml(t('po.sup_inv_date'))}</label>
      <input type="date" id="poSupInvDate" value="${escapeHtml(po.supplierInvoice?.date || new Date().toISOString().split('T')[0])}">`,
    onSave(modal) {
      const number = modal.querySelector('#poSupInvNum').value.trim();
      const amount = parseFloat(modal.querySelector('#poSupInvAmount').value) || 0;
      const date   = modal.querySelector('#poSupInvDate').value;
      po.supplierInvoice = { number, amount, date };
      // Check discrepancy: compare invoiced amount vs. PO expected amount
      const expectedAmt = (po.weightOrdered || 0) * ((po.unitCost || 0) / 1000);
      po.invoiceDiscrepancy = expectedAmt > 0 && Math.abs(amount - expectedAmt) > 1;
      saveAll();
      renderPurchaseOrders();
      toast(t('common.save'), 'success');
      return true;
    }
  });
}

/* ============================================================
   Feature 6 (this batch): Client portal export
   ============================================================ */
function exportClientPortal(clientId) {
  const c = clients.find(x => x.id === clientId);
  if (!c) return;
  const displayName = localName(c);
  const orders = printLog.filter(o => o.clientId === clientId)
    .sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const activeOrders = orders.filter(o => !['completed','quote'].includes(o.status));
  const completedOrders = orders.filter(o => o.status === 'completed');
  const outstanding = orders
    .filter(o => payStatus(o) !== 'paid')
    .reduce((s, o) => s + Math.max(0, +o.price - (+o.paidAmount || 0)), 0);

  const statusColors = {
    pending: '#f59e0b', printing: '#3b82f6', post: '#8b5cf6',
    qc: '#a78bfa', completed: '#22c55e', on_hold: '#f97316', quote: '#94a3b8'
  };
  const statusSteps = ['pending','printing','post','qc','completed'];

  const stepperHtml = (order) => {
    const si = statusSteps.indexOf(order.status);
    return `<div style="display:flex;gap:4px;align-items:center;margin-top:6px;font-size:10px;">
      ${statusSteps.map((st, i) => {
        const done = i < si;
        const cur  = i === si;
        const col  = cur ? (statusColors[st] || '#94a3b8') : (done ? '#22c55e' : '#374151');
        return `<span style="background:${col};color:#fff;padding:2px 7px;border-radius:4px;opacity:${cur?1:done?0.7:0.35};">${escapeHtml(st)}</span>${i < statusSteps.length-1 ? `<span style="color:#555;font-size:9px;">›</span>` : ''}`;
      }).join('')}
    </div>`;
  };

  const bizName = (settings.bizEn || settings.bizAr || 'Khayt');
  const portalIsAr = i18n.current === 'ar';
  const portalLang = portalIsAr ? 'ar' : 'en';
  const PL = {
    activeOrders:      portalIsAr ? 'طلبات نشطة'   : 'Active orders',
    completed:         portalIsAr ? 'مكتملة'        : 'Completed',
    outstandingBal:    portalIsAr ? 'الرصيد المستحق': 'Outstanding balance',
    date:              portalIsAr ? 'التاريخ'       : 'Date',
    project:           portalIsAr ? 'المشروع'       : 'Project',
    status:            portalIsAr ? 'الحالة'        : 'Status',
    amount:            portalIsAr ? 'المبلغ'        : 'Amount',
    payment:           portalIsAr ? 'الدفع'         : 'Payment',
    paid:              portalIsAr ? '✓ مدفوع'      : '✓ Paid',
    outstanding:       portalIsAr ? 'مستحق'         : 'Outstanding',
    paymentInfo:       portalIsAr ? 'معلومات الدفع' : 'Payment Information',
    orderPortal:       portalIsAr ? 'بوابة الطلبات' : 'Order portal for',
    generatedBy:       portalIsAr ? 'أُنشئ بواسطة Khayt' : 'Generated by Khayt',
  };
  const rowsHtml = orders.map(o => {
    const isPaid = payStatus(o) === 'paid';
    return `<tr style="border-bottom:1px solid #2a2a2a;">
      <td style="padding:8px;font-size:12px;white-space:nowrap;color:#888;">${escapeHtml(o.date || '')}</td>
      <td style="padding:8px;font-size:12px;"><strong style="color:#e2e8f0;">${escapeHtml(o.project || o.id)}</strong><div style="font-size:10px;color:#666;">${escapeHtml(o.id)}</div>
        ${!['completed','quote'].includes(o.status) ? stepperHtml(o) : ''}
      </td>
      <td style="padding:8px;"><span style="background:${statusColors[o.status]||'#555'};color:#fff;padding:2px 8px;border-radius:10px;font-size:11px;">${escapeHtml(o.status)}</span></td>
      <td style="padding:8px;text-align:right;font-weight:600;color:#4ade80;">${fmtPrice(o.price)}</td>
      <td style="padding:8px;text-align:center;font-size:11px;color:${isPaid?'#4ade80':'#f87171'};">${isPaid ? PL.paid : PL.outstanding}</td>
    </tr>`;
  }).join('');

  const paymentBlock = settings.paymentInstructions
    ? `<div style="margin-top:24px;padding:16px;background:#1a1a2e;border-radius:8px;border:1px solid #2a2a3e;">
        <h3 style="margin:0 0 8px;color:#94a3b8;font-size:13px;">${escapeHtml(PL.paymentInfo)}</h3>
        <p style="margin:0;color:#cbd5e1;font-size:13px;white-space:pre-line;">${escapeHtml(settings.paymentInstructions)}</p>
      </div>` : '';

  const html = `<!DOCTYPE html>
<html lang="${portalLang}" dir="${portalIsAr ? 'rtl' : 'ltr'}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>${escapeHtml(displayName)} — Client Portal — ${escapeHtml(bizName)}</title>
  <style>
    * { box-sizing: border-box; }
    body { font-family: -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif; background:#0f0f0f; color:#e2e8f0; margin:0; padding:20px; }
    .header { background:linear-gradient(135deg,#1e1e3f,#2d2d5a); padding:24px 28px; border-radius:12px; margin-bottom:20px; }
    h1 { margin:0 0 4px; font-size:1.4rem; color:#a78bfa; }
    .subtitle { color:#94a3b8; font-size:13px; }
    .stats { display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); gap:12px; margin-bottom:20px; }
    .stat-card { background:#1a1a2e; border:1px solid #2a2a3e; border-radius:8px; padding:14px 16px; }
    .stat-val { font-size:1.5rem; font-weight:700; color:#a78bfa; }
    .stat-lbl { font-size:11px; color:#64748b; margin-top:2px; }
    table { width:100%; border-collapse:collapse; background:#111; border-radius:8px; overflow:hidden; }
    th { padding:10px 8px; text-align:left; font-size:11px; color:#64748b; border-bottom:1px solid #2a2a2a; }
    @media(max-width:600px){ td,th { padding:6px 4px; font-size:11px; } }
  </style>
</head>
<body>
  <div class="header">
    <h1>${escapeHtml(bizName)}</h1>
    <div class="subtitle">${escapeHtml(PL.orderPortal)} ${escapeHtml(displayName)}</div>
  </div>
  <div class="stats">
    <div class="stat-card"><div class="stat-val">${activeOrders.length}</div><div class="stat-lbl">${escapeHtml(PL.activeOrders)}</div></div>
    <div class="stat-card"><div class="stat-val">${completedOrders.length}</div><div class="stat-lbl">${escapeHtml(PL.completed)}</div></div>
    <div class="stat-card"><div class="stat-val">${fmtPrice(outstanding)}</div><div class="stat-lbl">${escapeHtml(PL.outstandingBal)}</div></div>
  </div>
  <table>
    <thead><tr>
      <th>${escapeHtml(PL.date)}</th><th>${escapeHtml(PL.project)}</th><th>${escapeHtml(PL.status)}</th><th style="text-align:right;">${escapeHtml(PL.amount)}</th><th style="text-align:center;">${escapeHtml(PL.payment)}</th>
    </tr></thead>
    <tbody>${rowsHtml}</tbody>
  </table>
  ${paymentBlock}
  <p style="text-align:center;color:#374151;font-size:11px;margin-top:24px;">${escapeHtml(PL.generatedBy)} · ${new Date().toISOString().split('T')[0]}</p>
</body>
</html>`;

  if (window.hubAPI?.saveHtml) {
    window.hubAPI.saveHtml(html, `client-portal-${c.id}.html`).then(() => {
      toast(t('cl.portal_saved'), 'success');
    }).catch(() => {
      toast(t('cl.portal_saved'), 'info');
    });
  } else {
    const blob = new Blob([html], { type: 'text/html' });
    downloadBlob(blob, `client-portal-${c.id}.html`);
    toast(t('cl.portal_saved'), 'info');
  }
}

/* ============================================================
   Work Order — internal shop-floor sheet (no pricing shown)
   ============================================================ */
function generateWorkOrder(id) {
  const order = printLog.find(o => o.id === id);
  if (!order) return;
  const area = $('#work-order-print-area');
  const isAr = i18n.current === 'ar';
  const dir  = isAr ? 'rtl' : 'ltr';
  const bizPrimary = isAr ? (settings.bizAr || settings.bizEn) : (settings.bizEn || settings.bizAr);
  const today = new Date().toISOString().split('T')[0];
  const linkedClient = order.clientId ? clients.find(c => c.id === order.clientId) : null;
  const clientName = (order.project || '').trim() || (linkedClient ? localName(linkedClient) : t('inv.walk_in'));
  const lines = (order.parts && order.parts.length > 0) ? order.parts
    : [{ name: order.project || order.id, qty: 1, material: '', weight: '', printTime: order.printTime || 0 }];
  const machine = order.machineId ? machines.find(m => m.id === order.machineId) : null;
  const customDataHtml = (settings.customFields || []).length > 0 && order.customData
    ? (settings.customFields || []).map(f => {
        const val = (order.customData || {})[f.id] || '';
        return val ? `<div class="meta-row"><span class="k">${escapeHtml(f.label)}</span><span class="v">${escapeHtml(val)}</span></div>` : '';
      }).join('')
    : '';

  area.innerHTML = `
    <div class="inv-wrap wo-wrap">
    <div class="inv-top-bar" style="background:#374151;"></div>
    <div class="inv" dir="${dir}" lang="${i18n.current}" style="--brand:#1f2937; --accent:#374151; --highlight:#f3f4f6;">
      <div class="inv-header">
        <div class="biz">
          <div class="mark">${safeBizLogo() ? `<img src="${safeBizLogo()}" style="max-height:50px; max-width:100px; object-fit:contain;" alt="logo">` : BRAND_MARK_SVG}</div>
          <div class="biz-name"><h1>${escapeHtml(bizPrimary || 'Khayt')}</h1></div>
        </div>
        <div class="doc">
          <div class="title">${escapeHtml(isAr ? 'أمر تشغيل داخلي' : 'Work Order')}</div>
          <div class="title-ar ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? 'Work Order' : 'أمر تشغيل داخلي')}</div>
          <div class="meta">
            <div class="meta-row"><span class="k">${escapeHtml(isAr ? 'رقم الأمر' : 'WO No.')}</span><span class="v">WO-${escapeHtml(order.id)}</span></div>
            <div class="meta-row"><span class="k">${escapeHtml(isAr ? 'التاريخ' : 'Date')}</span><span class="v">${escapeHtml(formatPrintDate(today))}</span></div>
            <div class="meta-row"><span class="k">${escapeHtml(isAr ? 'تاريخ التسليم' : 'Due')}</span><span class="v">${order.dueDate ? escapeHtml(formatPrintDate(order.dueDate)) : '—'}</span></div>
            ${machine ? `<div class="meta-row"><span class="k">${escapeHtml(isAr ? 'الآلة' : 'Machine')}</span><span class="v">${escapeHtml(machine.name)}</span></div>` : ''}
            ${customDataHtml}
          </div>
        </div>
      </div>

      <div class="bill-to">
        <div class="label"><span>${escapeHtml(isAr ? 'العميل' : 'Client')}</span></div>
        <div>
          <div class="name">${escapeHtml(clientName)}</div>
          ${order.notes ? `<div class="name-sub">${escapeHtml(order.notes)}</div>` : ''}
        </div>
      </div>

      <table class="lines">
        <thead>
          <tr>
            <th>${escapeHtml(isAr ? 'الجزء' : 'Part')}</th>
            <th style="text-align:center; width:40px;">${escapeHtml(isAr ? 'الكمية' : 'Qty')}</th>
            <th style="width:120px;">${escapeHtml(isAr ? 'المادة' : 'Material')}</th>
            <th style="width:80px;">${escapeHtml(isAr ? 'اللون' : 'Colour')}</th>
            <th style="width:80px; text-align:center;">${escapeHtml(isAr ? 'الوزن (غ)' : 'Weight (g)')}</th>
            <th style="width:80px; text-align:center;">${escapeHtml(isAr ? 'الوقت (س)' : 'Time (h)')}</th>
            <th style="width:100px;">${escapeHtml(isAr ? 'الإعدادات' : 'Settings')}</th>
            <th style="width:100px;">${escapeHtml(isAr ? 'الملف' : 'File')}</th>
          </tr>
        </thead>
        <tbody>
          ${lines.map(p => {
            const invItem = p.filamentId ? inventory.find(f => f.id === p.filamentId) : null;
            const filamentName = invItem?.material || (p.material || '');
            // Feature 4: Include spool print settings in work order
            const printSettingsStr = invItem && (invItem.printTemp || invItem.bedTemp)
              ? [
                  invItem.printTemp ? `${invItem.printTemp}°C` : '',
                  invItem.bedTemp   ? `Bed: ${invItem.bedTemp}°C` : '',
                  invItem.maxSpeed  ? `${invItem.maxSpeed}mm/s` : '',
                ].filter(Boolean).join(' / ')
              : '';
            const settings_str = [
              p.infill ? `${p.infill}%` : '',
              p.layerHeight ? `${p.layerHeight}mm` : '',
              p.supports ? (isAr ? 'دعامات' : 'Supports') : '',
              printSettingsStr
            ].filter(Boolean).join(', ');
            return `<tr>
              <td>${escapeHtml(p.name || order.project || '')}</td>
              <td class="center">${escapeHtml(String(p.qty || 1))}</td>
              <td>${escapeHtml(filamentName)}</td>
              <td style="font-size:11px;">${escapeHtml(p.colour || invItem?.colourVariant || '—')}</td>
              <td class="center">${p.weight ? escapeHtml(String(+p.weight)) : '—'}</td>
              <td class="center">${p.printTime ? escapeHtml((+p.printTime).toFixed(1)) : '—'}</td>
              <td style="font-size:10px;">${escapeHtml(settings_str)}</td>
              <td style="font-size:10px; color:#4a8ee8;">${escapeHtml(p.fileRef || '—')}</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>

      <div class="wo-checks" style="margin-top:20px;">
        ${(settings.postChecklist || []).length > 0 ? `
          <div style="font-size:12px; font-weight:600; margin-bottom:8px;">${escapeHtml(isAr ? 'قائمة التحقق بعد الطباعة' : 'Post-Processing Checklist')}</div>
          ${settings.postChecklist.map(ch => `
            <div style="display:flex; align-items:center; gap:8px; margin-bottom:5px;">
              <div style="width:14px;height:14px;border:1.5px solid #666;border-radius:3px;flex-shrink:0;"></div>
              <span style="font-size:12px;">${escapeHtml(ch.label)}</span>
            </div>`).join('')}` : ''}
      </div>

      <div style="margin-top:28px; display:flex; justify-content:space-between; gap:32px;">
        <div style="flex:1; border-top:1px solid #ccc; padding-top:8px; font-size:12px; color:#888;">${escapeHtml(isAr ? 'المشغّل' : 'Operator')}</div>
        <div style="flex:1; border-top:1px solid #ccc; padding-top:8px; font-size:12px; color:#888;">${escapeHtml(isAr ? 'المراجع' : 'Reviewed by')}</div>
        <div style="flex:1; border-top:1px solid #ccc; padding-top:8px; font-size:12px; color:#888;">${escapeHtml(isAr ? 'التاريخ والوقت' : 'Date / Time')}</div>
      </div>
    </div>
    </div>`;

  setTimeout(() => window.print(), 80);
}

function renderInvoice(order, { qrSvg, payQrSvg = '', total, vatAmount, subtotal, vatRate, shipping = 0 }) {
  const area = $('#invoice-print-area');
  const issuedDate = formatPrintDate(order.date);
  const issuedTime = order.timestamp ? new Date(order.timestamp).toTimeString().slice(0, 5) : '';
  // Feature 1: use per-client currency if set
  const invCurrencyCode = clientCurrency(order.clientId);
  const invCurObj = CURRENCIES[invCurrencyCode] || CURRENCIES[settings.currency] || CURRENCIES.SAR;
  const invCurrSym = invCurObj.symbol;

  // Direction follows the current app language. The invoice is always bilingual,
  // but the primary label (larger, bolder) matches the user's working language.
  const isAr = i18n.current === 'ar';
  const dir = isAr ? 'rtl' : 'ltr';
  // Numeral formatting helper — only converts when in Arabic mode with the toggle on
  const num = (v) => (isAr && settings.useArabicNumerals) ? toArabicNumerals(v) : String(v);
  const isPaid = (order.paymentStatus === 'paid');

  // Label pairs — (primary, secondary). Primary = working language.
  const isQuoteDoc = order.status === 'quote';
  const L = {
    invoice:    isAr ? (isQuoteDoc ? ['عرض سعر','Quotation'] : ['فاتورة','Invoice'])
                     : (isQuoteDoc ? ['Quotation','عرض سعر'] : ['Invoice','فاتورة']),
    no:         isAr ? ['رقم',                 'No.']             : ['No.',               'رقم'],
    date:       isAr ? ['التاريخ',             'Date']            : ['Date',              'التاريخ'],
    time:       isAr ? ['الوقت',               'Time']            : ['Time',              'الوقت'],
    billTo:     isAr ? ['الفاتورة إلى',        'Bill to']         : ['Bill to',           'الفاتورة إلى'],
    description:isAr ? ['الوصف',               'Description']     : ['Description',       'الوصف'],
    qty:        isAr ? ['الكمية',              'Qty']             : ['Qty',               'الكمية'],
    amount:     isAr ? ['الإجمالي',            'Amount']          : ['Amount',            'الإجمالي'],
    subtotal:   isAr ? ['الإجمالي الفرعي',    'Subtotal']        : ['Subtotal',          'الإجمالي الفرعي'],
    vat:        isAr ? [`ضريبة القيمة (${vatRate || 15}٪)`, `VAT (${vatRate || 15}%)`] : [`VAT (${vatRate || 15}%)`, `ضريبة القيمة (${vatRate || 15}%)`],
    totalDue:   isAr ? ['الإجمالي المستحق',   'Total due']       : ['Total due',         'الإجمالي المستحق'],
    qrLabel:    isAr ? ['رمز هيئة الزكاة — امسح للتحقق', 'ZATCA QR — scan to verify']
                     : ['ZATCA QR — scan to verify',     'رمز هيئة الزكاة — امسح للتحقق'],
    legal:      settings.enableZatca
                  ? (isAr ? 'فاتورة متوافقة مع المرحلة الأولى من هيئة الزكاة والضريبة والجمارك'
                           : 'ZATCA Phase 1 compliant invoice with TLV-encoded QR code.')
                  : (isAr ? `صادرة بواسطة Khayt · ${t('inv.generated_by') || 'Professional Invoice'}`
                           : `Generated by Khayt · ${t('inv.generated_by') || 'Professional Invoice'}`),
  };

  // Pretty label: primary on top, smaller secondary underneath
  const pair = (k) => {
    const [p, s] = L[k];
    return `${escapeHtml(p)} <span class="sub${isAr ? ' ltr' : ' rtl'}">${escapeHtml(s)}</span>`;
  };

  // Bill-to: real client name, OR generic walk-in label
  const linkedClient = order.clientId ? clients.find(c => c.id === order.clientId) : null;
  const hasName = (order.project || '').trim().length > 0;
  const billToName = hasName ? order.project : t('inv.walk_in');
  const billToSub  = hasName
    ? (linkedClient ? renderClientSub(linkedClient) : '')
    : `<div class="name-sub">${isAr ? 'بدون عميل محدد' : 'No specific client'}</div>`;

  // Lines
  const orderExtraLines = order.extraLines || [];
  const orderExtraTotal = orderExtraLines.reduce((s, l) => s + (+l.amount || 0), 0);
  const lines = (order.parts && order.parts.length > 0)
    ? order.parts
    : [{ name: t('inv.services_default'), material: order.material, printTime: order.printTime, baseCost: order.price }];
  const totalBase = lines.reduce((s, p) => s + (+p.baseCost || 0), 0);
  // Pool for parts = total price minus shipping minus extra lines (fixed fees)
  const partsPool = +order.price - (+order.shippingCost || 0) - orderExtraTotal;
  const linesHtml = lines.map(p => {
    const share = totalBase > 0 ? (p.baseCost / totalBase) * partsPool : partsPool / lines.length;
    const meta = [
      p.material,
      p.printTime ? `${p.printTime} hrs` : '',
      p.printWeight ? `${Math.round(p.printWeight)} g` : '',
      p.layerHeight ? `${p.layerHeight}mm` : '',
      p.infill ? `${p.infill}% infill` : '',
      p.profile || ''
    ].filter(Boolean).join(' · ');
    return `
      <tr>
        <td>
          <div class="desc-en">${escapeHtml(p.name)}</div>
          ${meta ? `<div class="meta">${escapeHtml(meta)}</div>` : ''}
        </td>
        <td class="center">${num(String(p.qty || 1))}</td>
        <td class="amount">${fmtMoney(share)} <span style="color:var(--ink-mute); font-weight:500;">${invCurrSym}</span></td>
      </tr>`;
  }).join('');
  // Extra charge lines
  const extraLinesHtml = orderExtraLines.map(l => `
      <tr>
        <td><div class="desc-en">${escapeHtml(l.label || t('calc.extra_label_ph'))}</div></td>
        <td class="center">1</td>
        <td class="amount">${fmtMoney(+l.amount || 0)} <span style="color:var(--ink-mute); font-weight:500;">${invCurrSym}</span></td>
      </tr>`).join('');

  // Compact contact line in the header
  const contactBits = [
    settings.phone, settings.email,
    settings.cr ? `CR ${settings.cr}` : '',
    settings.vat ? `VAT ${settings.vat}` : ''
  ].filter(Boolean).join(' · ');

  // Choose business name & address based on language
  const bizPrimary    = isAr ? (settings.bizAr || settings.bizEn) : (settings.bizEn || settings.bizAr);
  const bizSecondary  = isAr ? (settings.bizEn || '') : (settings.bizAr || '');
  const addrPrimary   = isAr ? (settings.addrAr || settings.addrEn) : (settings.addrEn || settings.addrAr);
  const addrSecondary = isAr ? (settings.addrEn || '') : (settings.addrAr || '');

  const taglinePrimary   = isAr ? (settings.taglineAr || settings.taglineEn || '') : (settings.taglineEn || settings.taglineAr || '');
  const taglineSecondary = isAr ? (settings.taglineEn || '') : (settings.taglineAr || '');

  // Brand color: amber for quotes, user-chosen (or default) for invoices
  const invBrand     = isQuoteDoc ? '#92400e' : (safeCssColor(settings.invAccentColor, '#5E2E14'));
  const invAccent    = isQuoteDoc ? '#d97706' : (safeCssColor(settings.invAccentColor, '#B8723D'));
  const invHighlight = isQuoteDoc ? '#fef3c7' : '#fcefdc';

  // Terms / conditions section
  const termsPrimary   = isAr ? (settings.invTermsAr || settings.invTermsEn || '') : (settings.invTermsEn || settings.invTermsAr || '');
  const termsSecondary = isAr ? (settings.invTermsEn || '') : (settings.invTermsAr || '');
  const termsSectionHtml = termsPrimary.trim() ? `
    <div class="inv-terms">
      <div class="label-strip">
        <span>${escapeHtml(isAr ? 'الشروط والأحكام' : 'Terms & Conditions')}</span>
        <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? 'Terms & Conditions' : 'الشروط والأحكام')}</span>
      </div>
      <p class="inv-terms-body">${escapeHtml(termsPrimary)}</p>
      ${termsSecondary ? `<p class="inv-terms-body sec">${escapeHtml(termsSecondary)}</p>` : ''}
    </div>` : '';

  // Hijri date display (always bilingual when toggle is on)
  const hijri = settings.useHijri ? hijriDate(order.date, 'short') : '';

  // Bank / payment info section — only render if at least one bank field is set
  const hasBank = (settings.bankName || settings.iban || settings.accountHolder);
  const bankSectionHtml = hasBank ? `
    <div class="bank-section">
      <div class="label-strip">
        <span>${escapeHtml(isAr ? 'بيانات الدفع' : 'Payment information')}</span>
        <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? 'Payment information' : 'بيانات الدفع')}</span>
      </div>
      <div class="bank-grid">
        ${settings.bankName ? `<span class="k">${escapeHtml(t('inv.bank'))}</span><span class="v">${escapeHtml(settings.bankName)}</span>` : ''}
        ${settings.accountHolder ? `<span class="k">${escapeHtml(t('inv.account'))}</span><span class="v">${escapeHtml(settings.accountHolder)}</span>` : ''}
        ${settings.iban ? `<span class="k">${escapeHtml(t('inv.iban'))}</span><span class="v" style="letter-spacing:0.05em;">${escapeHtml(settings.iban.replace(/(.{4})/g, '$1 ').trim())}</span>` : ''}
      </div>
      ${(settings.acceptedPayments && settings.acceptedPayments.length > 0) ? `
        <div class="accepted-strip">
          <span class="label">${escapeHtml(t('inv.accepted'))}</span>
          <span class="methods">
            ${settings.acceptedPayments.map(m => `<span class="pm-pill ${m}">${escapeHtml(t('pay.method.' + m))}</span>`).join('')}
          </span>
        </div>` : ''}
      ${payQrSvg ? `
        <div class="pay-qr-row">
          <div class="pay-qr-code">${payQrSvg}</div>
          <div class="pay-qr-label">
            <span>${escapeHtml(isAr ? 'امسح للدفع' : 'Scan to pay')}</span>
            <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? 'Scan to pay' : 'امسح للدفع')}</span>
          </div>
        </div>` : ''}
    </div>` : '';

  // "Paid" stamp overlay
  const paidStampHtml = isPaid ? `<div class="paid-stamp">${escapeHtml(isAr ? 'مدفوع' : 'PAID')}</div>` : '';

  area.innerHTML = `
    <div class="inv-wrap">
    <div class="inv-top-bar" style="background:${invBrand};"></div>
    <div class="inv" dir="${dir}" lang="${i18n.current}" style="--brand:${invBrand}; --accent:${invAccent}; --highlight:${invHighlight};">
      ${paidStampHtml}

      <div class="inv-header">
        <div class="biz">
          <div class="mark">${safeBizLogo() ? `<img src="${safeBizLogo()}" style="max-height:80px; max-width:150px; object-fit:contain;" alt="logo">` : BRAND_MARK_SVG}</div>
          <div class="biz-name">
            <h1>${escapeHtml(bizPrimary || 'Khayt')}</h1>
            ${taglinePrimary ? `<div class="biz-tagline">${escapeHtml(taglinePrimary)}</div>` : ''}
            ${taglineSecondary ? `<div class="biz-tagline sec ${isAr ? 'ltr' : 'ar'}">${escapeHtml(taglineSecondary)}</div>` : ''}
            ${bizSecondary ? `<div class="biz-ar ${isAr ? 'ltr' : 'ar'}">${escapeHtml(bizSecondary)}</div>` : ''}
            <div class="biz-meta">
              ${addrPrimary ? `<p>${escapeHtml(addrPrimary)}</p>` : ''}
              ${addrSecondary ? `<p class="${isAr ? 'ltr' : 'ar-line ar'}">${escapeHtml(addrSecondary)}</p>` : ''}
              ${contactBits ? `<p>${escapeHtml(contactBits)}</p>` : ''}
            </div>
          </div>
        </div>

        <div class="doc">
          <div class="title">${escapeHtml(L.invoice[0])}</div>
          <div class="title-ar ${isAr ? 'ltr' : 'ar'}">${escapeHtml(L.invoice[1])}</div>
          <div class="meta">
            <div class="meta-row">
              <span class="k">${escapeHtml(L.no[0])}</span>
              <span class="v">${escapeHtml(num(order.id))}</span>
            </div>
            <div class="meta-row">
              <span class="k">${escapeHtml(L.date[0])}</span>
              <span class="v">${escapeHtml(num(issuedDate))}</span>
            </div>
            ${hijri ? `
            <div class="meta-row">
              <span class="k">${escapeHtml(t('inv.hijri'))}</span>
              <span class="v">${escapeHtml(num(hijri))}</span>
            </div>` : ''}
            ${issuedTime ? `
            <div class="meta-row">
              <span class="k">${escapeHtml(L.time[0])}</span>
              <span class="v">${escapeHtml(num(issuedTime))}</span>
            </div>` : ''}
            ${order.clientRef ? `
            <div class="meta-row">
              <span class="k">${escapeHtml(isAr ? 'مرجع العميل' : 'Client Ref.')}</span>
              <span class="v">${escapeHtml(order.clientRef)}</span>
            </div>` : ''}
          </div>
        </div>
      </div>

      <div class="bill-to">
        <div class="label">
          <span>${escapeHtml(L.billTo[0])}</span>
          <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(L.billTo[1])}</span>
        </div>
        <div>
          <div class="name">${escapeHtml(billToName)}${(() => {
            if (!order.clientId || !settings.loyaltyEnabled) return '';
            const tierObj = getClientTier(order.clientId);
            if (!tierObj) return '';
            return ` <span style="display:inline-block;background:#D88A3D;color:#fff;font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;vertical-align:middle;margin-inline-start:4px;">${escapeHtml(tierObj.name)}</span>`;
          })()}</div>
          ${billToSub}
        </div>
      </div>

      <table class="lines">
        <thead>
          <tr>
            <th>${pair('description')}</th>
            <th style="text-align:center; width: 60px;">${pair('qty')}</th>
            <th class="th-amount" style="width: 150px;">${pair('amount')}</th>
          </tr>
        </thead>
        <tbody>${linesHtml}${extraLinesHtml}</tbody>
      </table>

      <div class="totals">
        ${settings.enableZatca ? `
        <div class="qr-box">
          <div class="qr-svg">${qrSvg || '<div style="font-size:11px;color:#888;padding:24px;">QR unavailable</div>'}</div>
          <div class="qr-label">
            <span>${escapeHtml(L.qrLabel[0])}</span>
            <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(L.qrLabel[1])}</span>
          </div>
        </div>` : ''}
        <div class="summary">
          <div class="row">
            <span class="label-en">${escapeHtml(L.subtotal[0])}</span>
            <span class="v">${order.priceBeforeDiscount ? fmtMoney(order.priceBeforeDiscount) : (subtotal || total)} ${invCurrSym}</span>
          </div>
          ${order.discountPct > 0 ? `
          <div class="row" style="color:#22c55e;">
            <span class="label-en">${escapeHtml(isAr ? `خصم (${order.discountPct}%)` : `Discount (${order.discountPct}%)`)}</span>
            <span class="v">−${fmtMoney(Math.max(0, (order.priceBeforeDiscount || 0) - ((+order.price || 0) - (+order.shippingCost || 0) - (+order.rushFeeAmount || 0))))} ${invCurrSym}</span>
          </div>` : ''}
          ${(+order.shippingCost || 0) > 0 ? `
          <div class="row">
            <span class="label-en">${escapeHtml(isAr ? 'رسوم الشحن' : 'Shipping')}</span>
            <span class="v">${fmtMoney(+order.shippingCost)} ${invCurrSym}</span>
          </div>` : ''}
          ${vatRate > 0 ? `
          <div class="row">
            <span class="label-en">${escapeHtml(L.vat[0])}</span>
            <span class="v">${vatAmount} ${invCurrSym}</span>
          </div>` : ''}
          <div class="row grand">
            <span>
              <span class="label-en">${escapeHtml(L.totalDue[0])}</span>
              <span class="label-ar ${isAr ? 'ltr' : 'ar'}">${escapeHtml(L.totalDue[1])}</span>
            </span>
            <span class="v">${total}<span class="unit">${invCurrSym}</span></span>
          </div>
          ${(() => {
            const orderCur = invCurrencyCode;
            const baseCur = settings.currency || 'SAR';
            const xrate = (settings.exchangeRates || {})[orderCur];
            if (orderCur && orderCur !== baseCur && xrate && xrate > 0) {
              const convertedAmt = fmtMoney((+order.price || 0) * xrate);
              const baseSym = (CURRENCIES[baseCur] || CURRENCIES.SAR).symbol;
              return `<div class="row" style="opacity:0.65;font-size:11px;border-top:1px dashed rgba(0,0,0,0.1);padding-top:4px;margin-top:4px;">
                <span class="label-en">${escapeHtml(isAr ? `المبلغ بـ ${baseCur}` : `Amount in ${baseCur}`)}</span>
                <span class="v">${convertedAmt}<span class="unit">${escapeHtml(baseSym)}</span></span>
              </div>`;
            }
            return '';
          })()}
        </div>
      </div>

      ${bankSectionHtml}

      ${(order.instalments && order.instalments.length > 0) ? `
      <div class="inv-notes-section" style="margin-top:12px;">
        <div class="label-strip">
          <span>${escapeHtml(isAr ? 'جدول الأقساط' : 'Payment Schedule')}</span>
          <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? 'Payment Schedule' : 'جدول الأقساط')}</span>
        </div>
        <table style="width:100%;border-collapse:collapse;font-size:11.5px;margin-top:4px;">
          <thead><tr style="color:var(--ink-mute);text-align:left;">
            <th style="padding:3px 6px;">${escapeHtml(isAr ? '#' : '#')}</th>
            <th style="padding:3px 6px;">${escapeHtml(isAr ? 'الاستحقاق' : 'Due date')}</th>
            <th style="padding:3px 6px;text-align:right;">${escapeHtml(isAr ? 'المبلغ' : 'Amount')}</th>
            <th style="padding:3px 6px;text-align:center;">${escapeHtml(isAr ? 'الحالة' : 'Status')}</th>
          </tr></thead>
          <tbody>
            ${order.instalments.map((ins, i) => `
            <tr style="border-top:1px solid rgba(0,0,0,.06);">
              <td style="padding:3px 6px;">${i + 1}</td>
              <td style="padding:3px 6px;">${escapeHtml(ins.dueDate ? formatPrintDate(ins.dueDate) : '—')}</td>
              <td style="padding:3px 6px;text-align:right;">${fmtMoney(+ins.amount || 0)} ${invCurrSym}</td>
              <td style="padding:3px 6px;text-align:center;color:${ins.paid ? 'var(--ink-success,#15803d)' : 'var(--ink-mute)'}">${ins.paid ? (isAr ? '✓ مدفوع' : '✓ Paid') : (isAr ? 'معلق' : 'Pending')}</td>
            </tr>`).join('')}
          </tbody>
        </table>
      </div>` : ''}

      ${(order.invoiceNotes || '').trim() ? `
      <div class="inv-notes-section">
        <div class="label-strip">
          <span>${escapeHtml(isAr ? 'ملاحظات' : 'Notes')}</span>
          <span class="sub ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? 'Notes' : 'ملاحظات')}</span>
        </div>
        <p class="inv-notes-body">${escapeHtml(order.invoiceNotes)}</p>
      </div>` : ''}

      ${termsSectionHtml}

      <div class="footer">
        <div class="thanks">${escapeHtml(isAr ? (settings.footerAr || t('inv.thank_you')) : (settings.footerEn || t('inv.thank_you')))}</div>
        ${(isAr ? settings.footerEn : settings.footerAr) ? `<div class="thanks-ar ${isAr ? 'ltr' : 'ar'}">${escapeHtml(isAr ? settings.footerEn : settings.footerAr)}</div>` : ''}
        <div class="legal">${escapeHtml(L.legal)}</div>
        ${settings.showBetaDisclaimer ? `<div class="legal" style="margin-top:4px;color:#e67e22;font-size:9.5px;opacity:0.75;">
          ${isAr
            ? '⚠️ تم إنشاؤه بتطبيق تجريبي (Beta) — يُرجى التحقق من جميع الأرقام قبل الاعتماد عليها'
            : '⚠️ Generated by beta software — please verify all figures before relying on them'}
        </div>` : ''}
      </div>

    </div>
    </div>`;

  // Apply Arabic numerals to body content after render (line items / amounts)
  if (isAr && settings.useArabicNumerals) {
    area.querySelectorAll('.amount, .v, .qty, td.center, td.amount, .biz-meta, .meta').forEach(el => {
      el.textContent = toArabicNumerals(el.textContent);
    });
  }
}

// Sub-line of contact info beneath the bill-to name (when client is linked)
function renderClientSub(c) {
  const bits = [c.phone, c.email].filter(Boolean).join(' · ');
  if (!bits) return '';
  return `<div class="name-sub">${escapeHtml(bits)}</div>`;
}

// Pretty date for invoice headers — e.g. "21 May 2026"
function formatPrintDate(isoDate) {
  if (!isoDate) return '';
  try {
    const d = new Date(isoDate);
    return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  } catch { return isoDate; }
}

